<body>
<canvas id="c"></canvas>
<script>
"use strict";
const cv=document.getElementById("c"),cx=cv.getContext("2d");
let W=0,H=0;
function resize(){W=cv.width=innerWidth;H=cv.height=innerHeight;}
addEventListener("resize",resize);resize();

// ---------- audio (WebAudio, no assets) ----------
let AC=null;
function ac(){if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();return AC;}
function noiseBuf(a,dur){const n=(a.sampleRate*dur)|0,b=a.createBuffer(1,n,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;return b;}
function popSfx(){const a=ac(),t=a.currentTime;
  const o=a.createOscillator(),g=a.createGain();
  o.type="sine";o.frequency.setValueAtTime(900,t);o.frequency.exponentialRampToValueAtTime(120,t+.09);
  g.gain.setValueAtTime(.5,t);g.gain.exponentialRampToValueAtTime(.001,t+.12);
  o.connect(g).connect(a.destination);o.start(t);o.stop(t+.13);
  const n=a.createBufferSource();n.buffer=noiseBuf(a,.06);
  const f=a.createBiquadFilter();f.type="highpass";f.frequency.value=1500;
  const ng=a.createGain();ng.gain.setValueAtTime(.35,t);ng.gain.exponentialRampToValueAtTime(.001,t+.06);
  n.connect(f).connect(ng).connect(a.destination);n.start(t);
}
function drawSfx(p){const a=ac(),t=a.currentTime;
  const n=a.createBufferSource();n.buffer=noiseBuf(a,.18);
  const f=a.createBiquadFilter();f.type="bandpass";f.frequency.setValueAtTime(400+600*p,t);f.frequency.linearRampToValueAtTime(2000,t+.18);f.Q.value=1.2;
  const g=a.createGain();g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.12+.15*p,t+.05);g.gain.exponentialRampToValueAtTime(.001,t+.2);
  n.connect(f).connect(g).connect(a.destination);n.start(t);
}
function releaseSfx(p){const a=ac(),t=a.currentTime;
  const o=a.createOscillator(),g=a.createGain();
  o.type="triangle";o.frequency.setValueAtTime(180+300*p,t);o.frequency.exponentialRampToValueAtTime(60,t+.15);
  g.gain.setValueAtTime(.3,t);g.gain.exponentialRampToValueAtTime(.001,t+.18);
  o.connect(g).connect(a.destination);o.start(t);o.stop(t+.2);
}
function thudSfx(){const a=ac(),t=a.currentTime;
  const o=a.createOscillator(),g=a.createGain();
  o.type="sine";o.frequency.setValueAtTime(110,t);o.frequency.exponentialRampToValueAtTime(45,t+.1);
  g.gain.setValueAtTime(.3,t);g.gain.exponentialRampToValueAtTime(.001,t+.12);
  o.connect(g).connect(a.destination);o.start(t);o.stop(t+.13);
}
function winSfx(){const a=ac(),t=a.currentTime;
  [523,659,784,1047].forEach((f,i)=>{const o=a.createOscillator(),g=a.createGain();o.type="square";o.frequency.value=f;
  g.gain.setValueAtTime(.0001,t+i*.09);g.gain.exponentialRampToValueAtTime(.15,t+i*.09+.02);g.gain.exponentialRampToValueAtTime(.001,t+i*.09+.25);
  o.connect(g).connect(a.destination);o.start(t+i*.09);o.stop(t+i*.09+.3);});
}
function loseSfx(){const a=ac(),t=a.currentTime;
  [330,277,220,165].forEach((f,i)=>{const o=a.createOscillator(),g=a.createGain();o.type="sawtooth";o.frequency.value=f;
  g.gain.setValueAtTime(.0001,t+i*.12);g.gain.exponentialRampToValueAtTime(.12,t+i*.12+.02);g.gain.exponentialRampToValueAtTime(.001,t+i*.12+.3);
  o.connect(g).connect(a.destination);o.start(t+i*.12);o.stop(t+i*.12+.35);});
}

